window.docContents[15].resolve({"/Sobolev-Spaces-and-Weak-Derivatives/Extension___-Trace___-and-Embeddings/#PDEAtlas--Sobolev-Spaces-and-Weak-Derivatives--Extension___-Trace___-and-Embeddings--Sobolev___-Morrey___-Poincar______-and-Hardy-Inequalities--Geometric-hypotheses":{"contents":"The geometric assumptions differ by theorem family.\n\n* Whole-space Sobolev and Morrey estimates require no boundary geometry.* Domain Sobolev and Morrey estimates use either an explicit extension\noperator or the operational bounded  atlas.* In positive dimension, the completed Poincaré theorem needs only a bounded\nset, because its source is already the zero-boundary closure.* Completed finite- Hardy quotients are available on the positive\nhalf-line and the flat upper half-space without further geometry, and on a\ngeneral domain through the operational atlas.\n\n","context":"PDEAtlas\u0009Sobolev Spaces and Weak Derivatives\u0009Extension, Trace, and Embeddings\u0009Sobolev, Morrey, Poincaré, and Hardy Inequalities","header":"4.3.4.3. Geometric hypotheses","id":"/Sobolev-Spaces-and-Weak-Derivatives/Extension___-Trace___-and-Embeddings/#PDEAtlas--Sobolev-Spaces-and-Weak-Derivatives--Extension___-Trace___-and-Embeddings--Sobolev___-Morrey___-Poincar______-and-Hardy-Inequalities--Geometric-hypotheses"}});